input.new_string:
const { trim, slugify } = require('../src/str');

test('trim', () => {
  assert.strictEqual(trim('  a  '), 'a');
});

test('slugify lowercases and hyphenates', () => {
  assert.strictEqual(slugify('Hello World'), 'hello-world');
});

test('slugify collapses runs of non-alphanumerics', () => {
  assert.strictEqual(slugify('a -- b__c!!!d'), 'a-b-c-d');
});

test('slugify strips leading and trailing separators', () => {
  assert.strictEqual(slugify('  !!Hello, World!!  '), 'hello-world');
  assert.strictEqual(slugify('---a---'), 'a');
});

test('slugify keeps digits', () => {
  assert.strictEqual(slugify('Issue 6: add slugify'), 'issue-6-add-slugify');
});

test('slugify returns empty string when nothing alphanumeric remains', () => {
  assert.strictEqual(slugify('   '), '');
  assert.strictEqual(slugify('!!!'), '');
});

